struct iter::impl::StarMapFn : PipeableAndBindFirst<StarMapFn> {
 private:
  template <typename Func, typename TupType, std::size_t... Is>
  TupleStarMapper<Func, TupType, Is...> helper_with_tuples(
      Func func, TupType&& tup, std::index_sequence<Is...>) const {
    return {std::move(func), std::forward<TupType>(tup)};
  }

  template <typename T, typename = void>
  struct is_tuple_like : std::false_type {};

  template <typename T>
  struct is_tuple_like<T,
      std::void_t<decltype(std::tuple_size<std::decay_t<T>>::value)>>
      : std::true_type {};

 public:
  template <typename Func, typename Seq>
  auto operator()(Func func, Seq&& sequence) const {
    if constexpr (is_tuple_like<Seq>{}) {
      return helper_with_tuples(std::move(func), std::forward<Seq>(sequence),
          std::make_index_sequence<
              std::tuple_size<std::decay_t<Seq>>::value>{});
    } else {
      return StarMapper<Func, Seq>{
          std::move(func), std::forward<Seq>(sequence)};
    }
  }

  using PipeableAndBindFirst<StarMapFn>::operator();
};

namespace iter {
  inline constexpr impl::StarMapFn starmap{};
}

namespace iter {
  namespace impl {
    struct UniqueEverseenFn : Pipeable<UniqueEverseenFn> {
     private:
      template <typename Container>
      using Key = std::decay_t<iterator_deref<Container>>;

     public:
      template <typename Container, typename Hash, typename KeyEqual>
      auto operator()(Container&& container, const Hash& hash,
          const KeyEqual& key_equal) const {
        // You can't pass a hash function or an equality function without
        // passing a bucket_count as well. We get the default bucket count here
        // the first time this function runs.
        static auto default_bucket_count =
            std::unordered_set<char>{}.bucket_count();
        using elem_type = iterator_deref<Container>;
        auto func =
            [elem_seen =
                    std::unordered_set<std::decay_t<elem_type>, Hash, KeyEqual>(
                        default_bucket_count, hash, key_equal)](
                const std::remove_reference_t<elem_type>& e) mutable {
              return elem_seen.insert(e).second;
            };
        return filter(func, std::forward<Container>(container));
      }

      template <typename Container>
      auto operator()(Container&& container) const {
        return (*this)(std::forward<Container>(container),
            std::hash<Key<Container>>{}, std::equal_to<Key<Container>>{});
      }
    };
  }

  inline constexpr impl::UniqueEverseenFn unique_everseen{};
}

struct UniqueJustseenFn
        : PipeableAndBindOptionalSecond<UniqueJustseenFn, Identity> {
     public:
      using PipeableAndBindOptionalSecond<UniqueJustseenFn, Identity>::
      operator();
      template <typename Container, typename KeyFunc>
      auto operator()(Container&& container, KeyFunc key_fn) const {
        // decltype(auto) return type in lambda so reference types are preserved
        return imap(
            [](auto&& group) -> decltype(auto) {
              return *get_begin(group.second);
            },
            groupby(std::forward<Container>(container), std::move(key_fn)));
      }
    };

