// Construct the accumulated view via the function object (default or custom)
// Note: This returns a lazy range with input-iterator semantics
if (use_custom) {
  // Custom accumulator that biases and adds, still closed over int to satisfy constraints
  auto func = [](int a, int b) { return a + b + 1; };
  auto acc = iter::accumulate(data, func);
  // Exercise the range safely: only dereference when begin()!=end()
  auto it = acc.begin();
  auto last = acc.end();
  if (it != last) {
    (void)*it;                 // first value
    // Step a small bounded number of times
    for (int steps = 0; steps < 5 && it != last; ++steps) {
      ++it;                    // may reach end
      if (it != last) { (void)*it; }
    }
  } else {
    // For empty container, property: begin()==end()
    FUZZ_ASSERT(it == last, "Accumulator begin must equal end for empty container");
  }
