  unsigned int in = (*FUZZ_PARAM(unsigned int) % max_inner);
  std::vector<int> sub; sub.reserve(in);
  for (unsigned int j = 0; j < in; ++j) sub.push_back((*vals)[(i + j) % 64]);
  expected_total += in;
  top.emplace_back(std::move(sub));
