    // Limit how many items we will consume (1..64)
    unsigned int limit = (*FUZZ_PARAM(unsigned int) % 64u) + 1u;

    // Prevent signed overflow when checking/consuming values: ensure that
    // start + (limit-1)*step stays within [lowest, max]
    const T lo = std::numeric_limits<T>::lowest();
    const T hi = std::numeric_limits<T>::max();

    // Use widened arithmetic to check bounds safely
    __int128 wide_start = static_cast<__int128>(start);
    __int128 wide_step  = static_cast<__int128>(step);
    __int128 wide_last  = wide_start + wide_step * static_cast<__int128>(limit - 1u);
    if (wide_last < static_cast<__int128>(lo) || wide_last > static_cast<__int128>(hi)) {
