    // Construct the (effectively) unbounded arithmetic sequence
    auto rng = iter::count(start, step);

    // Consume up to `limit` elements, asserting arithmetic progression
    T expected = start;
    unsigned int seen = 0u;
    for (auto v : rng) {
        // Property: the nth value equals start + n*step
        FUZZ_ASSERT(v == expected, "iter::count progression property failed");

        // Prepare for next step, guarding against overflow by construction
        expected = static_cast<T>(static_cast<__int128>(expected) + static_cast<__int128>(step));

        if (++seen >= limit) { break; }
    }

    // If the range could not yield even one element (should not happen), bail
    if (seen == 0u) { FUZZ_BAIL(); }
